// Copyright 2024 Apheleia
//
// Description:
// Apheleia Verification Library (AVL) Benchmark
//
// Arithmetic constraints - relational operators and addition / subtraction, and
// nothing else. No sets, no bitwise operators, no implications.
//
// This file is compiled unchanged by both flavours of the benchmark. Clock and
// reset are generated by the cocotb testbench in ../cocotb/arithmetic.py, which
// also runs the iteration loop, so the two flavours share an identical harness.
//
// Only the randomization itself differs, and it is the sole thing inside the
// `ifdef below.

`timescale 1ns/1ps

module arithmetic_bench (
    input logic clk,
    input logic rst_n
);

    // Common to both flavours - lets the testbench confirm that both ran for
    // the same number of clock cycles.
    int unsigned cycles = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycles <= 0;
        end
        else begin
            cycles <= cycles + 1;
        end
    end

`ifdef BENCH_SV_RANDOMIZE
    // -----------------------------------------------------------------------
    // Randomization under test - SystemVerilog classes and constraints.
    // -----------------------------------------------------------------------

    class arithmetic_item;

        rand bit [15:0] a;
        rand bit [15:0] b;
        rand bit [15:0] c;
        rand bit [15:0] d;

        // Every constraint here controls a single variable - there are no
        // dependencies between the fields. See the implication benchmark for
        // those.

        // Bounded above and below.
        constraint c_a { a >= 16'd100;
                         a <= 16'd10000; }

        // Bounded above and below, both strict.
        constraint c_b { b > 16'd250;
                         b < 16'd20000; }

        // An inequality, and an upper bound.
        constraint c_c { c != 16'd0;
                         c <= 16'd1000; }

        // Addition inside the comparison. The upper bound keeps the sum clear
        // of the wrap at 16 bits.
        constraint c_d { d <= 16'd30000;
                         d + 16'd1000 > 16'd5000; }

    endclass : arithmetic_item

    arithmetic_item  item;
    bit              enable   = 1'b1;
    int unsigned     burst    = 1;
    longint unsigned checksum = 0;
    int unsigned     count    = 0;

    // Written only by the quality run, which is untimed - see +dump.
    int              dump_fd  = 0;
    string           dump_file;

    initial begin
        // Cleared for the baseline run, which measures the harness on its own.
        void'($value$plusargs("randomize=%d", enable));
        void'($value$plusargs("burst=%d", burst));

        if ($value$plusargs("dump=%s", dump_file)) begin
            dump_fd = $fopen(dump_file, "w");
            $fwrite(dump_fd, "a:16,b:16,c:16,d:16\n");
        end
    end

    always @(posedge clk) begin
        if (rst_n && enable) begin
            repeat (burst) begin
                // A fresh item per randomization, the way a testbench builds
                // a fresh sequence item per transaction, rather than one item
                // reused - which would let a solver amortize work across draws.
                item = new();

                if (item.randomize() == 0) begin
                    $fatal(1, "randomization failed on iteration %0d", count);
                end

                if (!(item.a >= 16'd100 && item.a <= 16'd10000)) begin
                    $fatal(1, "c_a violated : a=%0d", item.a);
                end
                if (!(item.b > 16'd250 && item.b < 16'd20000)) begin
                    $fatal(1, "c_b violated : b=%0d", item.b);
                end
                if (!(item.c != 16'd0 && item.c <= 16'd1000)) begin
                    $fatal(1, "c_c violated : c=%0d", item.c);
                end
                if (!(item.d <= 16'd30000 && (16'(item.d + 16'd1000) > 16'd5000))) begin
                    $fatal(1, "c_d violated : d=%0d", item.d);
                end

                if (dump_fd != 0) begin
                    $fwrite(dump_fd, "%0d,%0d,%0d,%0d\n", item.a, item.b, item.c, item.d);
                end

                checksum += 64'(item.a) + 64'(item.b) + 64'(item.c) + 64'(item.d);
                count    += 1;
            end
        end
    end

    final begin
        if (dump_fd != 0) $fclose(dump_fd);
        $display("BENCH_RESULT flavour=sv iterations=%0d checksum=%0d", count, checksum);
    end
`endif

endmodule : arithmetic_bench
